// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address owner, address caller) public {
        vm.assume(owner != address(0));
        vm.assume(caller != address(0));
        vm.assume(owner != caller);
        vm.prank(address(0));
        c.transferOwnership(owner);
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        if (caller == owner) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}
